def subtract(a, b):
    # Filter out empty intervals and sort
    a_valid = sorted([interval for interval in a if interval[0] < interval[1]])
    b_valid = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_valid:
        return []

    if not b_valid:
        return a_valid

    # Merge overlapping intervals in a
    a_merged = []
    for start, end in a_valid:
        if a_merged and a_merged[-1][1] >= start:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Merge overlapping intervals in b
    b_merged = []
    for start, end in b_valid:
        if b_merged and b_merged[-1][1] >= start:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    result = []

    for a_start, a_end in a_merged:
        current_start = a_start

        for b_start, b_end in b_merged:
            if b_end <= current_start:
                # b interval ends before current segment
                continue
            if b_start >= a_end:
                # b interval starts after current a interval
                break

            if b_start > current_start:
                # Gap before b interval
                result.append([current_start, b_start])

            current_start = max(current_start, b_end)

        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge adjacent intervals
    if not result:
        return []

    merged_result = [result[0]]
    for start, end in result[1:]:
        if merged_result[-1][1] == start:
            merged_result[-1][1] = end
        else:
            merged_result.append([start, end])

    return merged_result

